import type { DateValue } from '@vercel/geistcn/components';
import { Calendar } from '@vercel/geistcn/components';
import { useState, type JSX } from 'react';
import type { RangeValue } from '@react-types/shared';
import { startOfDay, subDays, subWeeks, subMonths, endOfDay } from 'date-fns';

export function Component(): JSX.Element {
  const [date, setDate] = useState<RangeValue<DateValue>>();
  const [date2, setDate2] = useState<RangeValue<DateValue>>();

  const now = new Date();

  const minDate = new Date(
    now.getFullYear(),
    now.getMonth() - 2,
    now.getDate(),
  );

  const maxDate = new Date(
    now.getFullYear(),
    now.getMonth() + 2,
    now.getDate(),
  );

  const presets = {
    'last-3-days': {
      text: 'Last 3 Days',
      start: startOfDay(subDays(new Date(), 3)),
      end: endOfDay(new Date()),
    },
    'last-7-days': {
      text: 'Last 7 Days',
      start: startOfDay(subWeeks(new Date(), 1)),
      end: endOfDay(new Date()),
    },
    'last-14-days': {
      text: 'Last 14 Days',
      start: startOfDay(subWeeks(new Date(), 2)),
      end: endOfDay(new Date()),
    },
    'last-month': {
      text: 'Last Month',
      start: startOfDay(subMonths(new Date(), 1)),
      end: endOfDay(new Date()),
    },
  };

  return (
    <div className="py-12 space-y-12">
      <div>
        <p className="text-copy-14 text-gray-900 mb-4 font-mono">small</p>
        <div className="flex flex-wrap items-start gap-x-4 gap-y-12">
          <Calendar
            allowClear
            size="small"
            onChange={setDate2}
            value={date2}
            minValue={minDate}
            maxValue={maxDate}
          />
          <Calendar
            allowClear
            compact
            size="small"
            onChange={setDate2}
            value={date2}
            minValue={minDate}
            maxValue={maxDate}
            presets={presets}
          />
          <Calendar
            allowClear
            stacked
            size="small"
            onChange={setDate2}
            value={date2}
            minValue={minDate}
            maxValue={maxDate}
            presets={presets}
          />
          <Calendar
            size="small"
            onChange={setDate}
            presets={presets}
            value={date}
          />
        </div>
      </div>
      <div>
        <p className="text-copy-14 text-gray-900 mb-4 font-mono">
          default / medium
        </p>
        <div className="flex flex-wrap items-start gap-x-4 gap-y-12">
          <Calendar
            allowClear
            onChange={setDate2}
            value={date2}
            minValue={minDate}
            maxValue={maxDate}
          />
          <Calendar
            allowClear
            compact
            onChange={setDate2}
            value={date2}
            minValue={minDate}
            maxValue={maxDate}
            presets={presets}
          />
          <Calendar
            allowClear
            stacked
            onChange={setDate2}
            value={date2}
            minValue={minDate}
            maxValue={maxDate}
            presets={presets}
          />
          <Calendar onChange={setDate} presets={presets} value={date} />
        </div>
      </div>
    </div>
  );
}

